def independent_synthetic_test(D_cal, k_cal, val_times, val_vals,
                               ic_val, x_obs, L=1.0, n_points=51):
    """跨初值合成測試，非物理 Validation；時空皆採線性插值。"""
    val_times = np.asarray(val_times, dtype=float).ravel()
    val_vals = np.asarray(val_vals, dtype=float).ravel()
    if val_times.size == 0 or val_times.shape != val_vals.shape:
        raise ValueError("時間與觀測值須等長非空")
    if (not np.all(np.isfinite(val_times)) or not np.all(np.isfinite(val_vals))
            or np.any(val_times < 0)):
        raise ValueError("合成觀測須有限且時間非負")
    if (np.ndim(x_obs) != 0 or not np.isfinite(x_obs)
            or x_obs < 0 or x_obs > L):
        raise ValueError("x_obs 須為域內有限純量")
    x, times, history = simulate_diffusion(
        D_cal, L=L, n_points=n_points, t_end=float(np.max(val_times)),
        k=k_cal, save_history=True, initial_cond=ic_val)
    sampled = np.array([np.interp(float(x_obs), x, state)
                        for state in history])
    preds = np.interp(val_times, np.asarray(times), sampled)
    return compute_rmse(val_vals, preds), np.asarray(preds)

